/*
 * Real NitroSDK ARM7 sequencer, running on an independent audio clock.
 *
 * The ARM9 game's PXI sender only enqueues immutable command-list pointers;
 * the audio producer executes the ORIGINAL SDK ARM7 command processor,
 * sequencer, envelopes and channel allocation. These symbols are in the
 * N7_ namespace, generated by objcopy --redefine-syms in the Makefile.
 *
 * No ARM9 OS calls, scheduler, PXI interrupts or libctru are made from
 * NitroPort_SoundRender. Alarm replies are queued for the game/platform
 * thread to deliver by NitroPort_SoundPumpReplies.
 */
#include <nitro.h>
#include <nitro_port.h>
#include <nitro_port_sound_chip.h>
#include "port_platform.h"
#include <nitro/snd/common/command.h>
#include <nitro/snd/common/work.h>
#include <nitro/snd/common/main.h>

#include <stdint.h>
#include <string.h>

#define SOUND_QUEUE_CAPACITY 32u
#define SOUND_ALARM_CAPACITY 128u
/* The ARM7 driver's tick: every SND_PROC_INTERVAL (2728) OS ticks, an OS
 * tick being 64 cycles of the 33.513982 MHz bus clock: 5.2095 ms, about 192
 * a second. In samples: 2728 * 64 * 32768 / 33513982 = 170.7. The phase
 * below counts in 1/33513982ths of a sample. (It was taken for 2728
 * microseconds once, and music played 1.9 times too fast.) */
#define SOUND_BUS_CLOCK 33513982ull
#define SOUND_TICK_SAMPLES ((uint64_t)SND_PROC_INTERVAL * 64u * NITRO_SOUND_RATE)

/* The ARM7 copy of the SDK's own functions and shared globals. */
extern void N7_SND_Init(u32 priority);
extern void N7_SND_CommandProc(void);
extern void N7_SND_UpdateExChannel(void);
extern void N7_SND_SeqMain(BOOL periodic);
extern void N7_SND_ExChannelMain(BOOL periodic);
extern void N7_SND_UpdateSharedWork(void);
extern u16 N7_SND_CalcRandom(void);

static NitroSoundChip sChip;
static volatile unsigned int sLock;
static volatile int sReady;
static const SNDCommand *sPending[SOUND_QUEUE_CAPACITY];
static unsigned sHead, sCount;
static u32 sAlarmReplies[SOUND_ALARM_CAPACITY];
static unsigned sAlarmHead, sAlarmCount;
static uint64_t sClock, sTickPhase;

typedef struct PortSoundAlarm {
    uint64_t due;
    uint64_t period;
    u32 message;
    int active;
} PortSoundAlarm;
static PortSoundAlarm sAlarms[16];

static void sound_lock(void)
{
    unsigned spins = 0;

    while (__sync_lock_test_and_set(&sLock, 1u)) {
        while (__atomic_load_n(&sLock, __ATOMIC_RELAXED)) {
            /* Short critical sections, so spin a little; then sleep, never
             * the ARM9 OS scheduler. The sleep matters: the sound thread
             * outranks the game's, so on the same CPU core a lock the game
             * holds is only let go if the sound thread stops spinning. */
            if (++spins >= 64u) {
                NitroPortPlatform_Sleep(50);
                spins = 0;
            }
        }
    }
}
static void sound_unlock(void)
{
    __sync_lock_release(&sLock);
}

/* ARM9 SDK status getters share this lock with the real ARM7 driver.
 * The same mutex covers every non-atomic SNDSharedWork status/variable
 * read and all audio-side writes, without entering the ARM9 scheduler. */
void NitroPort_SoundSharedLock(void)
{
    sound_lock();
}
void NitroPort_SoundSharedUnlock(void)
{
    sound_unlock();
}

void NitroPort_ResetSoundState(void)
{
    sound_lock();
    sHead = sCount = 0;
    sAlarmHead = sAlarmCount = 0;
    sClock = sTickPhase = 0;
    memset(sAlarms, 0, sizeof(sAlarms));
    NitroSound_Reset(&sChip, NITRO_SOUND_RATE);
    /* Executes Nintendo's ARM7 init, but not its OS/CreateThread path. */
    N7_SND_Init(0);
    __atomic_store_n(&sReady, 1, __ATOMIC_RELEASE);
    sound_unlock();
}

/* Called only while the audio lock is held, from patched ARM7
 * snd_command.c's original SND_CommandProc. */
const SNDCommand *NitroPort_SoundPopCommand(void)
{
    const SNDCommand *result;
    if (!sCount) return NULL;
    result = sPending[sHead];
    sHead = (sHead + 1u) % SOUND_QUEUE_CAPACITY;
    --sCount;
    return result;
}

void NitroPort_HandleSound(int tag, u32 data, BOOL err)
{
    (void)tag;
    if (err || data == 0u) return; /* request-command-proc wakeup */
    sound_lock();
    /* The ARM9 SDK allows at most eight in-flight command lists, so a
     * 32-entry FIFO cannot overflow during supported operation. */
    if (sCount == SOUND_QUEUE_CAPACITY) {
        sound_unlock();
        NitroPort_Log("[nitro] ARM7 sound queue overrun");
        return;
    }
    sPending[(sHead + sCount) % SOUND_QUEUE_CAPACITY] =
        (const SNDCommand *)(uintptr_t)data;
    ++sCount;
    sound_unlock();
}

/* Called by patched ARM7 snd_alarm.c under the audio lock. Values are
 * in OS ticks (1/64 of the original DS CPU clock), as in the SDK. */
void NitroPort_SoundAlarmStart(int no, u64 tick, u64 period, u32 message)
{
    if ((unsigned)no >= 16u) return;
    sAlarms[no].due = sClock + tick;
    sAlarms[no].period = period;
    sAlarms[no].message = message;
    sAlarms[no].active = 1;
}
void NitroPort_SoundAlarmStop(int no)
{
    if ((unsigned)no < 16u) sAlarms[no].active = 0;
}

static void sound_tick(void)
{
    unsigned i;
    /* One original SND_Main iteration, precisely the driver's order. */
    N7_SND_UpdateExChannel();
    N7_SND_CommandProc();
    N7_SND_SeqMain(TRUE);
    N7_SND_ExChannelMain(TRUE);
    N7_SND_UpdateSharedWork();
    (void)N7_SND_CalcRandom();

    sClock += SND_PROC_INTERVAL;
    for (i = 0; i < 16u; ++i) {
        PortSoundAlarm *a = &sAlarms[i];
        if (!a->active || sClock < a->due) continue;
        if (sAlarmCount < SOUND_ALARM_CAPACITY) {
            sAlarmReplies[(sAlarmHead + sAlarmCount) % SOUND_ALARM_CAPACITY]
                = a->message;
            ++sAlarmCount;
        }
        if (a->period) a->due += a->period;
        else a->active = 0;
    }
}

/* Audio-side clock, completely independent of game frames and OS_Halt.
 * Exactly 32768 output samples correspond to one second; an original
 * sequencer tick fires every 5.2095 ms (SOUND_TICK_SAMPLES), including
 * fractional sample timing.
 *
 * Mixed a stretch at a time: up to the next tick (about 171 samples), with
 * the lock held for one stretch only, so the game never waits for long.
 * Commands the game sends are taken at the start of the next stretch, at
 * most 5.2 ms later (the DS's ARM7 took them on its next tick, too). */
void NitroPort_SoundRender(int16_t *stereo, size_t frames)
{
    size_t done = 0;
    if (!stereo) return;
    if (!__atomic_load_n(&sReady, __ATOMIC_ACQUIRE)) {
        memset(stereo, 0, frames * 4u);
        return;
    }
    while (done < frames) {
        uint64_t toTick;
        size_t n;

        sound_lock();
        if (sCount) {
            N7_SND_CommandProc();
            N7_SND_UpdateSharedWork();
        }
        /* Samples until the one that reaches the next tick, included. */
        toTick = (SOUND_TICK_SAMPLES - sTickPhase + SOUND_BUS_CLOCK - 1u) / SOUND_BUS_CLOCK;
        n = frames - done;
        if (toTick < n) n = (size_t)toTick;
        NitroSound_Mix(&sChip, stereo + 2u * done, n);
        sTickPhase += SOUND_BUS_CLOCK * (uint64_t)n;
        if (sTickPhase >= SOUND_TICK_SAMPLES) {
            sTickPhase -= SOUND_TICK_SAMPLES;
            sound_tick();
        }
        sound_unlock();
        done += n;
    }
}

/* Called by the game thread (e.g. its OnFrame hook), NOT the audio thread.
 * NitroPort_Arm7Reply invokes the virtual ARM9 FIFO interrupt/scheduler. */
void NitroPort_SoundPumpReplies(void)
{
    for (;;) {
        u32 msg;
        sound_lock();
        if (!sAlarmCount) {
            sound_unlock();
            break;
        }
        msg = sAlarmReplies[sAlarmHead];
        sAlarmHead = (sAlarmHead + 1u) % SOUND_ALARM_CAPACITY;
        --sAlarmCount;
        sound_unlock();
        NitroPort_Arm7Reply(PXI_FIFO_TAG_SOUND, msg, FALSE);
    }
}
